// resize-queue.js
var RESIZE_SETTLE_MS = 250;
function queueResize(target) {
  clearTimeout(target.resizeTimer);
  target.resizeTimer = setTimeout(() => {
    target.resizeTimer = null;
    if (target.deferResize?.()) {
      queueResize(target);
      return;
    }
    target.resize();
  }, RESIZE_SETTLE_MS);
  target.resizeQueued = (target.resizeQueued || 0) + 1;
}

